/* ---------- verses (per source text) ----------
   V(verse_id, book_id, chapter, verse_num, source_text, language_code, text_en, apparatus) */
function V(verse_id,book_id,chapter,verse_num,source_text,language_code,text_en,apparatus){
  return {verse_id:verse_id,book_id:book_id,chapter:chapter,verse_num:verse_num,source_text:source_text,language_code:language_code,text_en:text_en,apparatus:apparatus||null};
}
